def proverb(*pieces, qualifier=None):
    if not pieces:
        return []

    lines = [
        f"For want of a {a} the {b} was lost."
        for a, b in zip(pieces, pieces[1:])
    ]

    first = pieces[0]
    if qualifier is not None:
        first = f"{qualifier} {first}"
    lines.append(f"And all for the want of a {first}.")

    return lines

